const seismicArrayScore = (shortSensors, deepSensors, relayTowers, ashWarning) => {
  const requiredSeconds = shortSensors * 12 + deepSensors * 20
    + (ashWarning ? relayTowers * 7 : 0);
  const relayCapacitySeconds = relayTowers * 48;
  const processedSeconds = Math.min(requiredSeconds, relayCapacitySeconds);
  const backloggedSeconds = Math.max(requiredSeconds - relayCapacitySeconds, 0);
  const scanRounds = Math.floor(requiredSeconds / 37);
  return processedSeconds + backloggedSeconds * 6 + scanRounds * 10;
};
