    pub conservation_score: i64,
    pub conservation_state: String,
}

pub fn score(canvas_crates: i64, textile_crates: i64, work_tables: i64, emergency_drying: bool) -> i64 {
    let canvas_work_minutes = canvas_crates * 9;
    let textile_work_minutes = textile_crates * 15;
