  const completedMinutes = Math.min(requiredMinutes, capacityMinutes);
  const deferredMinutes = Math.max(requiredMinutes - capacityMinutes, 0);
  const conservationRounds = Math.floor(requiredMinutes / 34);

  return completedMinutes + deferredMinutes * 7 + conservationRounds * 11;
};

export const handle = (value: RequestInput) => {
  const canvasWorkMinutes = value.canvas_crates * 9;
  const textileWorkMinutes = value.textile_crates * 15;
  const dryingSetupMinutes = value.emergency_drying ? value.work_tables * 6 : 0;
  const conservationRequiredMinutes = canvasWorkMinutes + textileWorkMinutes + dryingSetupMinutes;
  const tableCapacityMinutes = value.work_tables * 43;
  const completedMinutes = Math.min(conservationRequiredMinutes, tableCapacityMinutes);
  const deferredMinutes = Math.max(conservationRequiredMinutes - tableCapacityMinutes, 0);

  return {
    crate_total: value.canvas_crates + value.textile_crates,
    canvas_work_minutes: canvasWorkMinutes,
    textile_work_minutes: textileWorkMinutes,
    drying_setup_minutes: dryingSetupMinutes,
    conservation_required_minutes: conservationRequiredMinutes,
    table_capacity_minutes: tableCapacityMinutes,
    completed_minutes: completedMinutes,
    deferred_minutes: deferredMinutes,
    conservation_rounds: Math.floor(conservationRequiredMinutes / 34),
    conservation_score: score(value.canvas_crates, value.textile_crates, value.work_tables, value.emergency_drying),
    conservation_state: deferredMinutes === 0 ? "preserved" : value.emergency_drying ? "emergency_queue" : "routine_queue",
  };
};

export async function loadParley() {
  return {
    museum_conservation_score: (canvasCrates: number, textileCrates: number, workTables: number, emergencyDrying: boolean) =>
      BigInt(score(canvasCrates, textileCrates, workTables, emergencyDrying)),
  };
}

