const museumConservationScore = (canvasCrates, textileCrates, workTables, emergencyDrying) => {
  const canvasWorkMinutes = canvasCrates * 9n;
  const textileWorkMinutes = textileCrates * 15n;
  const dryingSetupMinutes = emergencyDrying ? workTables * 6n : 0n;
  const requiredMinutes = canvasWorkMinutes + textileWorkMinutes + dryingSetupMinutes;
  const capacityMinutes = workTables * 43n;
  const completedMinutes = requiredMinutes < capacityMinutes ? requiredMinutes : capacityMinutes;
  const deferredMinutes = requiredMinutes > capacityMinutes ? requiredMinutes - capacityMinutes : 0n;
  const rounds = requiredMinutes / 34n;
  return completedMinutes + deferredMinutes * 7n + rounds * 11n;
};
export async function loadParley() { return { museum_conservation_score: museumConservationScore }; }

