const museumConservationScore = (canvasCrates, textileCrates, workTables, emergencyDrying) => {
  const requiredMinutes = canvasCrates * 9 + textileCrates * 15 + (emergencyDrying ? workTables * 6 : 0);
  const capacityMinutes = workTables * 43;
  const completedMinutes = Math.min(requiredMinutes, capacityMinutes);
  const deferredMinutes = Math.max(requiredMinutes - capacityMinutes, 0);
  const conservationRounds = Math.floor(requiredMinutes / 34);
  return completedMinutes + deferredMinutes * 7 + conservationRounds * 11;
};
