use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub short_sensors: i64,
    pub deep_sensors: i64,
    pub relay_towers: i64,
    pub ash_warning: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.short_sensors >= 0 && self.deep_sensors >= 0 && self.relay_towers >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub sensor_total: i64,
    pub short_scan_seconds: i64,
    pub deep_scan_seconds: i64,
    pub ash_sync_seconds: i64,
    pub array_required_seconds: i64,
    pub relay_capacity_seconds: i64,
    pub processed_seconds: i64,
    pub backlogged_seconds: i64,
    pub scan_rounds: i64,
    pub array_score: i64,
    pub array_state: String,
}

pub fn score(short_sensors: i64, deep_sensors: i64, relay_towers: i64, ash_warning: bool) -> i64 {
    let short_scan_seconds = short_sensors * 12;
    let deep_scan_seconds = deep_sensors * 20;
    let ash_sync_seconds = if ash_warning { relay_towers * 7 } else { 0 };
    let array_required_seconds = short_scan_seconds + deep_scan_seconds + ash_sync_seconds;
    let relay_capacity_seconds = relay_towers * 48;
    let processed_seconds = array_required_seconds.min(relay_capacity_seconds);
    let backlogged_seconds = (array_required_seconds - relay_capacity_seconds).max(0);
    let scan_rounds = array_required_seconds / 37;

    processed_seconds + backlogged_seconds * 6 + scan_rounds * 10
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let short_scan_seconds = v.short_sensors * 12;
    let deep_scan_seconds = v.deep_sensors * 20;
    let ash_sync_seconds = if v.ash_warning { v.relay_towers * 7 } else { 0 };
    let array_required_seconds = short_scan_seconds + deep_scan_seconds + ash_sync_seconds;
    let relay_capacity_seconds = v.relay_towers * 48;
    let processed_seconds = array_required_seconds.min(relay_capacity_seconds);
    let backlogged_seconds = (array_required_seconds - relay_capacity_seconds).max(0);
    let scan_rounds = array_required_seconds / 37;

    ResponseOutput {
        sensor_total: v.short_sensors + v.deep_sensors,
        short_scan_seconds,
        deep_scan_seconds,
        ash_sync_seconds,
        array_required_seconds,
        relay_capacity_seconds,
        processed_seconds,
        backlogged_seconds,
        scan_rounds,
        array_score: processed_seconds + backlogged_seconds * 6 + scan_rounds * 10,
        array_state: if backlogged_seconds == 0 {
            "aligned"
        } else if v.ash_warning {
            "ash_backlog"
        } else {
            "routine_backlog"
        }
        .into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_seismic_array_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

