const seismicArrayScore = (shortSensors, deepSensors, relayTowers, ashWarning) => {
  const shortScanSeconds = shortSensors * 12;
  const deepScanSeconds = deepSensors * 20;
  const ashSyncSeconds = ashWarning ? relayTowers * 7 : 0;
  const arrayRequiredSeconds = shortScanSeconds + deepScanSeconds + ashSyncSeconds;
  const relayCapacitySeconds = relayTowers * 48;
  const processedSeconds = Math.min(arrayRequiredSeconds, relayCapacitySeconds);
  const backloggedSeconds = Math.max(arrayRequiredSeconds - relayCapacitySeconds, 0);
  const scanRounds = Math.floor(arrayRequiredSeconds / 37);
  return BigInt(processedSeconds + backloggedSeconds * 6 + scanRounds * 10);
};
