const seismicArrayScore=(shortSensors,deepSensors,relayTowers,ashWarning)=>{
  const short=BigInt(shortSensors);
  const deep=BigInt(deepSensors);
  const towers=BigInt(relayTowers);
  const required=short*12n+deep*20n+(ashWarning?towers*7n:0n);
  const capacity=towers*48n;
  const processed=required<capacity?required:capacity;
  const backlog=required>capacity?required-capacity:0n;
