class RequestInput(BaseModel):
 model_config=ConfigDict(extra='forbid',strict=True); short_sensors:int=Field(ge=0); deep_sensors:int=Field(ge=0); relay_towers:int=Field(ge=0); ash_warning:bool
def seismic_array_score(s:int,d:int,t:int,a:bool)->int:
 required=s*12+d*20+(t*7 if a else 0); capacity=t*48; backlog=max(required-capacity,0)
 return min(required,capacity)+backlog*6+(required//37)*10
