export type RequestInput = {
  freight_barges: number;
  tour_barges: number;
  lock_chambers: number;
  flood_protocol: boolean;
};

export const clearance = (freight: number, tours: number, chambers: number, floodProtocol: boolean) => {
  const required = freight * 10 + tours * 17 + (floodProtocol ? chambers * 8 : 0);
  const capacity = chambers * 45;
  return Math.max(capacity - Math.min(required, capacity), 0);
};

export const handle = (value: RequestInput) => {
  const freight_lock_units = value.freight_barges * 10;
  const tour_lock_units = value.tour_barges * 17;
  const flood_lock_units = value.flood_protocol ? value.lock_chambers * 8 : 0;
  const lock_required_units = freight_lock_units + tour_lock_units + flood_lock_units;
  const lock_capacity_units = value.lock_chambers * 45;
  const passed_lock_units = Math.min(lock_required_units, lock_capacity_units);
  const held_lock_units = Math.max(lock_required_units - lock_capacity_units, 0);

  return {
    barge_total: value.freight_barges + value.tour_barges,
    freight_lock_units,
    tour_lock_units,
    flood_lock_units,
    lock_required_units,
    lock_capacity_units,
    passed_lock_units,
    held_lock_units,
    clearance_units: Math.max(lock_capacity_units - passed_lock_units, 0),
    canal_state: held_lock_units === 0 ? "clear" : value.flood_protocol ? "flood_hold" : "routine_hold",
  };
};

export async function loadParley() {
  return {
    canal_clearance_units: (freight: number, tours: number, chambers: number, floodProtocol: boolean) =>
      BigInt(clearance(freight, tours, chambers, floodProtocol)),
  };
}

