    pub canvas_crates: i64,
    pub textile_crates: i64,
    pub work_tables: i64,
    pub emergency_drying: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.canvas_crates >= 0 && self.textile_crates >= 0 && self.work_tables >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub crate_total: i64,
    pub canvas_work_minutes: i64,
    pub textile_work_minutes: i64,
    pub drying_setup_minutes: i64,
    pub conservation_required_minutes: i64,
    pub table_capacity_minutes: i64,
    pub completed_minutes: i64,
    pub deferred_minutes: i64,
    pub conservation_rounds: i64,
    pub conservation_score: i64,
    pub conservation_state: String,
}

pub fn score(canvas_crates: i64, textile_crates: i64, work_tables: i64, emergency_drying: bool) -> i64 {
    let canvas_work_minutes = canvas_crates * 9;
    let textile_work_minutes = textile_crates * 15;
    let drying_setup_minutes = if emergency_drying { work_tables * 6 } else { 0 };
    let conservation_required_minutes = canvas_work_minutes + textile_work_minutes + drying_setup_minutes;
    let table_capacity_minutes = work_tables * 43;
    let completed_minutes = conservation_required_minutes.min(table_capacity_minutes);
    let deferred_minutes = (conservation_required_minutes - table_capacity_minutes).max(0);
    let conservation_rounds = conservation_required_minutes / 34;

    completed_minutes + deferred_minutes * 7 + conservation_rounds * 11
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let canvas_work_minutes = v.canvas_crates * 9;
    let textile_work_minutes = v.textile_crates * 15;
    let drying_setup_minutes = if v.emergency_drying { v.work_tables * 6 } else { 0 };
    let conservation_required_minutes = canvas_work_minutes + textile_work_minutes + drying_setup_minutes;
    let table_capacity_minutes = v.work_tables * 43;
    let completed_minutes = conservation_required_minutes.min(table_capacity_minutes);
    let deferred_minutes = (conservation_required_minutes - table_capacity_minutes).max(0);

    ResponseOutput {
        crate_total: v.canvas_crates + v.textile_crates,
        canvas_work_minutes,
        textile_work_minutes,
        drying_setup_minutes,
        conservation_required_minutes,
        table_capacity_minutes,
        completed_minutes,
        deferred_minutes,
        conservation_rounds: conservation_required_minutes / 34,
        conservation_score: score(v.canvas_crates, v.textile_crates, v.work_tables, v.emergency_drying),
        conservation_state: if deferred_minutes == 0 {
