export type RequestInput = {
  short_sensors: number;
  deep_sensors: number;
  relay_towers: number;
  ash_warning: boolean;
};

export const score = (
  shortSensors: number,
  deepSensors: number,
  relayTowers: number,
  ashWarning: boolean,
) => {
  const requiredSeconds =
    shortSensors * 12 + deepSensors * 20 + (ashWarning ? relayTowers * 7 : 0);
  const capacitySeconds = relayTowers * 48;
  const processedSeconds = Math.min(requiredSeconds, capacitySeconds);
  const backloggedSeconds = Math.max(requiredSeconds - capacitySeconds, 0);
  const scanRounds = Math.floor(requiredSeconds / 37);

  return processedSeconds + backloggedSeconds * 6 + scanRounds * 10;
};

export const handle = (value: RequestInput) => {
  const shortScanSeconds = value.short_sensors * 12;
  const deepScanSeconds = value.deep_sensors * 20;
  const ashSyncSeconds = value.ash_warning ? value.relay_towers * 7 : 0;
  const arrayRequiredSeconds = shortScanSeconds + deepScanSeconds + ashSyncSeconds;
  const relayCapacitySeconds = value.relay_towers * 48;
  const backloggedSeconds = Math.max(arrayRequiredSeconds - relayCapacitySeconds, 0);

  return {
    sensor_total: value.short_sensors + value.deep_sensors,
    short_scan_seconds: shortScanSeconds,
    deep_scan_seconds: deepScanSeconds,
    ash_sync_seconds: ashSyncSeconds,
    array_required_seconds: arrayRequiredSeconds,
    relay_capacity_seconds: relayCapacitySeconds,
    processed_seconds: Math.min(arrayRequiredSeconds, relayCapacitySeconds),
    backlogged_seconds: backloggedSeconds,
    scan_rounds: Math.floor(arrayRequiredSeconds / 37),
    array_score: score(
      value.short_sensors,
      value.deep_sensors,
      value.relay_towers,
      value.ash_warning,
    ),
    array_state:
      backloggedSeconds === 0
        ? "aligned"
        : value.ash_warning
          ? "ash_backlog"
          : "routine_backlog",
  };
};

export async function loadParley() {
  return {
    seismic_array_score: (
      shortSensors: number,
      deepSensors: number,
      relayTowers: number,
      ashWarning: boolean,
    ) => BigInt(score(shortSensors, deepSensors, relayTowers, ashWarning)),
  };
}

