const seismicArrayScore = (shortSensors, deepSensors, relayTowers, ashWarning) => {
  const shortScanSeconds = shortSensors * 12;
  const deepScanSeconds = deepSensors * 20;
  const ashSyncSeconds = ashWarning ? relayTowers * 7 : 0;
  const required = shortScanSeconds + deepScanSeconds + ashSyncSeconds;
  const capacity = relayTowers * 48;
  const processed = Math.min(required, capacity);
  const backlogged = Math.max(required - capacity, 0);
  const scanRounds = Math.floor(required / 37);

  return processed + backlogged * 6 + scanRounds * 10;
};

export async function loadParley() { return { seismic_array_score: seismicArrayScore }; }

