const museumConservationScore=(canvasCrates,textileCrates,workTables,emergencyDrying)=>{
  const required=canvasCrates*9+textileCrates*15+(emergencyDrying?workTables*6:0);
  const capacity=workTables*43;
  const completed=Math.min(required,capacity);
  const deferred=Math.max(required-capacity,0);
  const rounds=Math.floor(required/34);
  return completed+deferred*7+rounds*11;
};
export async function loadParley() { return { museum_conservation_score: museumConservationScore }; }

