from pydantic import BaseModel,ConfigDict,Field
class RequestInput(BaseModel):
 model_config=ConfigDict(extra='forbid',strict=True); canvas_crates:int=Field(ge=0); textile_crates:int=Field(ge=0); work_tables:int=Field(ge=0); emergency_drying:bool
def museum_conservation_score(c: int, t: int, w: int, e: bool) -> int:
 work = c * 9 + t * 15 + (w * 6 if e else 0)
 capacity = w * 43
 completed = min(work, capacity)
 deferred = max(work - capacity, 0)
 return completed + deferred * 7 + (work // 34) * 11
