const museumConservationScore = (canvasCrates, textileCrates, workTables, emergencyDrying) => {
  const canvas = BigInt(canvasCrates);
  const textile = BigInt(textileCrates);
  const tables = BigInt(workTables);
  const required = canvas * 9n + textile * 15n + (emergencyDrying ? tables * 6n : 0n);
  const capacity = tables * 43n;
  const completed = required < capacity ? required : capacity;
  const deferred = required > capacity ? required - capacity : 0n;
  return completed + deferred * 7n + (required / 34n) * 11n;
};
export async function loadParley() { return { museum_conservation_score: museumConservationScore }; }

