export type RequestInput={seedling_rows:number;fruit_rows:number;heat_pumps:number;frost_cycle:boolean};export const score=(s:number,f:number,p:number,c:boolean)=>{const r=s*8+f*14+(c?p*5:0),x=p*41;return Math.min(r,x)+Math.max(r-x,0)*5+Math.trunc(r/23)*7};export const handle=(v:RequestInput)=>{const s=v.seedling_rows*8,f=v.fruit_rows*14,c=v.frost_cycle?v.heat_pumps*5:0,r=s+f+c,p=v.heat_pumps*41,d=Math.max(r-p,0),delivered=Math.min(r,p);return {row_total:v.seedling_rows+v.fruit_rows,seedling_heat_units:s,fruit_heat_units:f,frost_heat_units:c,heat_required_units:r,pump_capacity_units:p,delivered_heat_units:delivered,heat_deficit_units:d,heat_reserve_units:Math.max(p-delivered,0),heating_cycles:Math.trunc(r/29),greenhouse_score:score(v.seedling_rows,v.fruit_rows,v.heat_pumps,v.frost_cycle),greenhouse_state:d===0?'balanced':v.frost_cycle?'frost_shortage':'heat_shortage'}};export async function loadParley(){return {thermal_greenhouse_score:(a:number,b:number,c:number,d:boolean)=>BigInt(score(a,b,c,d))}}
