export type RequestInput = {
  canvas_crates: number;
  textile_crates: number;
  work_tables: number;
  emergency_drying: boolean;
};

export const score = (
  canvasCrates: number,
  textileCrates: number,
  workTables: number,
  emergencyDrying: boolean,
) => {
  const requiredMinutes =
    canvasCrates * 9 +
    textileCrates * 15 +
    (emergencyDrying ? workTables * 6 : 0);
  const capacityMinutes = workTables * 43;
  const completedMinutes = Math.min(requiredMinutes, capacityMinutes);
  const deferredMinutes = Math.max(requiredMinutes - capacityMinutes, 0);
  const conservationRounds = Math.floor(requiredMinutes / 34);

  return completedMinutes + deferredMinutes * 7 + conservationRounds * 11;
};

export const handle = (value: RequestInput) => {
  const canvasWorkMinutes = value.canvas_crates * 9;
  const textileWorkMinutes = value.textile_crates * 15;
  const dryingSetupMinutes = value.emergency_drying ? value.work_tables * 6 : 0;
  const requiredMinutes = canvasWorkMinutes + textileWorkMinutes + dryingSetupMinutes;
  const capacityMinutes = value.work_tables * 43;
  const deferredMinutes = Math.max(requiredMinutes - capacityMinutes, 0);

  return {
    crate_total: value.canvas_crates + value.textile_crates,
    canvas_work_minutes: canvasWorkMinutes,
    textile_work_minutes: textileWorkMinutes,
    drying_setup_minutes: dryingSetupMinutes,
    conservation_required_minutes: requiredMinutes,
    table_capacity_minutes: capacityMinutes,
    completed_minutes: Math.min(requiredMinutes, capacityMinutes),
    deferred_minutes: deferredMinutes,
    conservation_rounds: Math.floor(requiredMinutes / 34),
    conservation_score: score(
      value.canvas_crates,
      value.textile_crates,
      value.work_tables,
      value.emergency_drying,
    ),
    conservation_state:
      deferredMinutes === 0
        ? "preserved"
        : value.emergency_drying
          ? "emergency_queue"
          : "routine_queue",
  };
};

export async function loadParley() {
  return {
    museum_conservation_score: (
      canvasCrates: number,
      textileCrates: number,
      workTables: number,
      emergencyDrying: boolean,
    ) => BigInt(score(canvasCrates, textileCrates, workTables, emergencyDrying)),
  };
}

